    const record: PrepareRecordV1 = { version: 1, transaction_id: input.transactionId, operation: input.operation, base_revision: input.state.root.host_revision, proposed_revision: revision, created_at: input.createdAt, prepared_operation: preparedOperation, lease_intents: input.leaseIntent ? [input.leaseIntent] : [], artifacts: input.artifacts ?? [] };
    const leasePort = { acquire: async (intent: TaskRecordV1["lease_intent"]): Promise<PreparedLeaseHandleV1> => { const owner = input.localOperation?.lease_owner ?? caller; const handle = await this.options.leases.acquire({ owner, sessionId: intent.session_id, taskId: intent.logical_key, reason: intent.reason }); if (owner.kind === "main") this.#rootLeases.set(intent.logical_key, handle); return { releaseWithoutWake: async (reason) => { this.#rootLeases.delete(intent.logical_key); await handle.releaseWithoutWake({ outcome: "cancelled", reason }); } }; }, retainUncertain: (transactionId: string, _intents: readonly any[], handles: readonly PreparedLeaseHandleV1[]) => { const taskId = input.leaseIntent?.logical_key; if (taskId && handles[0]) this.#uncertain.set(transactionId, { taskId, handle: handles[0] }); } };
